-- 0062_打板评分正式数据.sql：将打板评分输入从供应商 payload 提升为正式字段，
-- 并为已发布策略的固定研究基准提供可版本化、可携带的事实表。

ALTER TABLE market_bar
  ADD COLUMN turnover numeric;

ALTER TABLE market_limit_event
  ADD COLUMN is_st boolean,
  ADD COLUMN is_new boolean,
  ADD COLUMN seal_money double precision,
  ADD COLUMN max_seal_money double precision,
  ADD COLUMN turnover double precision;

UPDATE market_limit_event
   SET is_st = CASE lower(source_payload ->> 'is_st')
                 WHEN 'true' THEN true WHEN 'false' THEN false ELSE NULL END,
       is_new = CASE lower(source_payload ->> 'is_new')
                  WHEN 'true' THEN true WHEN 'false' THEN false ELSE NULL END,
       seal_money = CASE
         WHEN source_payload ->> 'seal_money' ~ '^[+-]?[0-9]+([.][0-9]+)?([eE][+-]?[0-9]+)?$'
         THEN (source_payload ->> 'seal_money')::double precision ELSE NULL END,
       max_seal_money = CASE
         WHEN source_payload ->> 'max_seal_money' ~ '^[+-]?[0-9]+([.][0-9]+)?([eE][+-]?[0-9]+)?$'
         THEN (source_payload ->> 'max_seal_money')::double precision ELSE NULL END,
       turnover = CASE
         WHEN source_payload ->> 'turnover' ~ '^[+-]?[0-9]+([.][0-9]+)?([eE][+-]?[0-9]+)?$'
         THEN (source_payload ->> 'turnover')::double precision ELSE NULL END;

ALTER TABLE market_limit_event
  ADD CONSTRAINT market_limit_event_seal_money_finite
    CHECK (seal_money IS NULL OR seal_money NOT IN ('Infinity'::float8, '-Infinity'::float8, 'NaN'::float8)),
  ADD CONSTRAINT market_limit_event_max_seal_money_finite
    CHECK (max_seal_money IS NULL OR max_seal_money NOT IN ('Infinity'::float8, '-Infinity'::float8, 'NaN'::float8)),
  ADD CONSTRAINT market_limit_event_turnover_finite
    CHECK (turnover IS NULL OR turnover NOT IN ('Infinity'::float8, '-Infinity'::float8, 'NaN'::float8));

CREATE TABLE strategy_score_benchmark (
  id                    bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  document_revision_id  bigint NOT NULL REFERENCES strategy_document_revision(id) ON DELETE RESTRICT,
  benchmark_code        text NOT NULL UNIQUE,
  training_start        date NOT NULL,
  training_end          date NOT NULL,
  methodology           text NOT NULL,
  distributions         jsonb NOT NULL CHECK (jsonb_typeof(distributions) = 'object'),
  sample_counts         jsonb NOT NULL CHECK (jsonb_typeof(sample_counts) = 'object'),
  source_summary        jsonb NOT NULL CHECK (jsonb_typeof(source_summary) = 'object'),
  sha256                text NOT NULL CHECK (sha256 ~ '^[0-9a-f]{64}$'),
  created_at            timestamptz NOT NULL DEFAULT now(),
  UNIQUE (document_revision_id),
  CHECK (training_end >= training_start)
);

