       benchmark.payload ->> 'methodology',
       benchmark.payload -> 'distributions',
       benchmark.payload -> 'sample_counts',
       benchmark.payload -> 'source_summary',
       benchmark.payload ->> 'sha256'
  FROM benchmark CROSS JOIN current_strategy;

WITH current_prompt AS (
  SELECT prompt.id AS prompt_id,
         prompt.current_revision_id AS base_revision_id,
         revision.content,
         $addition$

## 打板确定性评分

1. 确认实际市场结构数据日后，必须调用一次 `limit_up_signal_query`，直接使用服务端按当前《打板策略》、版本化固定研究基准和完整涨停池计算的全部候选、抱团分、主升分、路线名次、信号等级、关键输入、风险和缺口。
2. 不得通过通用数据库查询或分页市场事件自行重算 `R↑/R↓`、分数、路线前 2 名和等级；不得把固定分数线误称为固定研究基准分布。工具返回 `success/partial` 时均以其确定性结果为准，`partial` 必须逐项保留实际缺口及影响。
3. 只有 `signals` 中的有效信号可以写入打板机会；`candidates` 中的接近阈值、未进路线前 2 名或 `data_insufficient` 标的不得补入。页面结构化证据必须与工具返回的主标签、精确等级、两分数、两名次、风险和实际数据日一致。
$addition$ AS addition
    FROM job_prompt prompt
    JOIN job_prompt_revision revision ON revision.id = prompt.current_revision_id
   WHERE prompt.code = 'daily_plan_flow'
     AND prompt.status = 'active'
     AND revision.content NOT LIKE '%## 打板确定性评分%'
), inserted AS (
  INSERT INTO job_prompt_revision
    (prompt_id, revision_no, content, sha256, source, base_revision_id, change_summary)
  SELECT current_prompt.prompt_id,
         (SELECT COALESCE(MAX(existing.revision_no), 0) + 1
            FROM job_prompt_revision existing WHERE existing.prompt_id = current_prompt.prompt_id),
         current_prompt.content || current_prompt.addition,
         encode(sha256(convert_to(current_prompt.content || current_prompt.addition, 'UTF8')), 'hex'),
         'user', current_prompt.base_revision_id,
         '每日计划直接读取版本化固定基准生成的确定性打板评分'
    FROM current_prompt
  RETURNING prompt_id, id
)
UPDATE job_prompt prompt
   SET current_revision_id = inserted.id, updated_at = now()
  FROM inserted
 WHERE prompt.id = inserted.prompt_id;
